import{_ as u,C as o,o as c,c as p,j as t,a,E as s,a8 as d}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/bFcob2p6u3A-640.webp",w="/schedule-dashboard/thumbs/yt/bFcob2p6u3A-1280.webp",n="/schedule-dashboard/thumbs/yt/1S4hx3wgvBE-640.webp",m="/schedule-dashboard/thumbs/yt/1S4hx3wgvBE-1280.webp",i="/schedule-dashboard/thumbs/yt/nRlqH4izAU8-640.webp",g="/schedule-dashboard/thumbs/yt/nRlqH4izAU8-1280.webp",I=JSON.parse('{"title":"AI Digest · Fri 27 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-27","routine":"digest"},"relativePath":"digest/2026-11-27.md","filePath":"digest/[date].md"}'),b={name:"digest/2026-11-27.md"},f=r+" 640w, "+w+" 1280w",y=n+" 640w, "+m+" 1280w",v=i+" 640w, "+g+" 1280w",k={id:"ai-digest-·-fri-27-nov-2026",tabindex:"-1"};function _(A,e,S,q,x,R){const l=o("Badge"),h=o("DayFilter");return c(),p("div",null,[t("h1",k,[e[0]||(e[0]=a("AI Digest · Fri 27 Nov 2026 ",-1)),s(l,{type:"tip",text:"3"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-fri-27-nov-2026","aria-label":'Permalink to "AI Digest · Fri 27 Nov 2026 <Badge type="tip" text="3" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 27 Nov 2026 · run date Fri 27 Nov 2026 · 3 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(' There are 2 new talks, both non-technical. The freshest is Jason Liu (OpenAI) on ambition, ownership and taste when execution is free (27 Nov, 1:30 AM IST). Before that, Justin McCarthy (Diffusion) argues against software factories for new ideas and for "brownfield" and "demand" factories instead (26 Nov, 7:30 PM IST). Software factories are a heavily repeated topic (30 prior videos), but his angle is new. Skim both.')]),t("p",null,[t("strong",null,"Better Stack:"),a(" There's 1 new video (26 Nov, 7:15 PM IST): rust-anything, a tool that verifies agent-written Rust ports. The 19× Prettier claim turns out to be 4.2× warm. It's concrete and worth watching. Better Stack's Shorts under 2 minutes were skipped.")])],-1)),s(h),e[5]||(e[5]=d('<div class="grid cards2"><article class="it full" id="v-bFcob2p6u3A" data-title="Execution Is Free. How Ambitious Are You? — Jason Liu, OpenAI" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=bFcob2p6u3A" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+f+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=bFcob2p6u3A" target="_blank" rel="noopener">Execution Is Free. How Ambitious Are You? — Jason Liu, OpenAI</a></h3><div class="meta">AI Engineer · Jason Liu, developer experience team at OpenAI · uploaded 27 Nov, 1:30 AM IST · 19:26</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:05 — a non-technical mindset talk; the taste-as-language section (7:05–12:30) is the useful part, and the rest is familiar inspiration.</div><div class="repeat">🔁 Repeat: &#39;AI writing quality / slop&#39; — seen 4 times before. New here: he concedes AI will create more slop and argues the fix is ownership: slop comes from people who stop caring about the work (&quot;self-erasure&quot;), not from the tool.</div><div class="sh">Ambition when execution is free</div><ul><li><strong>From developer experience to everything experience:</strong> He joined OpenAI in March, before the Codex app took off. He lists this year&#39;s launches: the Codex app, biology work, sites, cybersecurity, voice and computer use, and recently math and physics, going &quot;from grade school math&quot; to tackling Navier-Stokes (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=100s" target="_blank" rel="noopener">1:40</a>)</li><li><strong>Three principles, three fears:</strong> Ambition isn&#39;t spending more tokens or running thousands of agents. It means (1) owning the work you ship, (2) being able to describe what good looks like, and (3) being curious enough to use AI in other fields. These answer three fears: more slop, losing critical thinking, and being replaced (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=115s" target="_blank" rel="noopener">1:55</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=170s" target="_blank" rel="noopener">2:50</a>)</li></ul><div class="sh">Ownership and slop</div><ul><li><strong>The painter and the camera:</strong> Quoting Walter Benjamin&#39;s <em>The Work of Art in the Age of Mechanical Reproduction</em>, he says photography moved creation from the hand to the eye and voice, much like voice-mode prompting now. A camera roll full of unseen photos is &quot;slop&quot;, but what matters is capturing the few key moments. He had no childhood photos because his family couldn&#39;t afford a camera (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=330s" target="_blank" rel="noopener">5:30</a>)</li><li><strong>Self-erasure is the real danger:</strong> A film with thousands of crew is still the director&#39;s, and open source quality rests on core maintainers. The difference between two people shipping 1,000 PRs is whether they care: use your own product, notice what breaks, and iterate, because great examples online are rarely one-shot (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=330s" target="_blank" rel="noopener">5:30</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=425s" target="_blank" rel="noopener">7:05</a>)</li></ul><div class="sh">Taste as language</div><ul><li><strong>Taste defined:</strong> He dislikes &quot;taste is the moat&quot; because it doesn&#39;t say what taste is. His definition is the ability to describe what you like and predict what others will like. In art school his judgment outran his skill, and &quot;make it pop&quot; a hundred times doesn&#39;t help (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=425s" target="_blank" rel="noopener">7:05</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>One phrase can change results:</strong> Steve&#39;s tweet &quot;find all the implicit state machines in my app&quot; made commenters&#39; apps about 20% faster. Using the generator–discriminator idea from ML, he says humans are now the discriminator: once model output matches your taste, you can&#39;t push it further (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=605s" target="_blank" rel="noopener">10:05</a>)</li><li><strong>&quot;If you want good taste, you have to eat&quot;:</strong> He had to learn typography, motion design and interaction patterns, and says the &quot;purple apps&quot; exist because their makers couldn&#39;t name what was wrong. His AI 3D prints looked like &quot;rectangles glued together&quot; until he studied sports cars and industrial design. Team leads should give people time to explore (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=605s" target="_blank" rel="noopener">10:05</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=790s" target="_blank" rel="noopener">13:10</a>)</li></ul><div class="sh">Pursue the fields you gave up</div><ul><li><strong>Cross-pollination:</strong> Michelangelo was sculptor, painter, architect and poet. A physicist founded molecular biology, and a mathematician led the Human Genome Project. Today an ML consultant used AI to help treat their dog&#39;s cancer, and a Hokkaido public servant built farm robots with ChatGPT and vision models (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=790s" target="_blank" rel="noopener">13:10</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=960s" target="_blank" rel="noopener">16:00</a>)</li><li><strong>His own side projects:</strong> He is learning drums with custom software, uses AI to learn Ableton and MIDI, uses computer use to learn new software, and 3D prints parts and builds chips. He says the Codex app and sites were &quot;acts of love&quot;, and OpenAI PMs now do engineering and engineers do design (<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=960s" target="_blank" rel="noopener">16:00</a>–<a href="https://www.youtube.com/watch?v=bFcob2p6u3A&amp;t=1140s" target="_blank" rel="noopener">19:00</a>)</li></ul></div></article><article class="it full" id="v-1S4hx3wgvBE" data-title="Stop Building Software Factories — Justin McCarthy, Diffusion" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=1S4hx3wgvBE" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=1S4hx3wgvBE" target="_blank" rel="noopener">Stop Building Software Factories — Justin McCarthy, Diffusion</a></h3><div class="meta">AI Engineer · Justin McCarthy, founder &amp; CEO of Diffusion · uploaded 26 Nov, 7:30 PM IST · 18:03</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:12 — the brownfield-vs-greenfield and demand-factory framing is a fresh angle on an overdone theme, but there&#39;s no technical detail.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 30 times before. New here: a contrarian take: stop sending new ideas through factories and run them only on &quot;brownfield&quot; products customers already pay for, then build a &quot;demand factory&quot; to find what customers will actually buy.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 97 times before. New here: little; it&#39;s a strategy talk with no technical setup (that&#39;s behind a QR code at the end).</div><div class="sh">Why &quot;stop building software factories&quot;</div><ul><li><strong>Where it started:</strong> He built his first factory in July last year on the Claude 4 models, before GPT-5 and the first Codex harness. Looping worked then, but only at huge token cost and with a hand-built &quot;Rube Goldberg contraption&quot; of loops (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=57s" target="_blank" rel="noopener">0:57</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=147s" target="_blank" rel="noopener">2:27</a>)</li><li><strong>Greenfield doesn&#39;t belong in a factory:</strong> When you&#39;re building something new you usually don&#39;t know what you want yet, so industrializing it gets you the wrong thing, too slowly, at too much cost. Decide first whether you&#39;re in discovery or working on something that already exists and works (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=147s" target="_blank" rel="noopener">2:27</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=192s" target="_blank" rel="noopener">3:12</a>)</li><li><strong>Brownfield is already specified:</strong> Customers pay for it, and usage, feedback and support tickets tell you what to keep. He mentions Jarred&#39;s Bun rewrite as an example of brownfield code that can now be rewritten, and says backlogs and tech debt are &quot;drying up&quot; (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=192s" target="_blank" rel="noopener">3:12</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li></ul><div class="sh">How a brownfield factory works</div><ul><li><strong>Promises and loops:</strong> At Diffusion every feature, price/cost and security property is a &quot;promise&quot; you don&#39;t want to regress, and each becomes a loop that feeds output back into input. His analogy is an amplifier: cut the feedback path and you only amplify noise (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=376s" target="_blank" rel="noopener">6:16</a>)</li><li><strong>Continuous, 24/7:</strong> Commits used to follow daily and weekly cycles. A factory keeping promises should look like a flat line of round-the-clock activity on &quot;is it slow, is it insecure&quot;, running in the background (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=376s" target="_blank" rel="noopener">6:16</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=511s" target="_blank" rel="noopener">8:31</a>)</li><li><strong>Factories simplify themselves:</strong> Skills get shorter and harnesses more general with each model release. Like SpaceX&#39;s Raptor 1 to Raptor 2 (more performance, fewer parts), models such as Astra, Fable and Carbon will simplify your factory if you can just barely get it working now (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=511s" target="_blank" rel="noopener">8:31</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li><li><strong>The instruction:</strong> &quot;The same, but faster, cheaper, safer&quot;, which nobody argues with as long as you aren&#39;t trading one for another. &quot;Better&quot; needs human taste, so keep it in discovery. He says standing one up takes about a week (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=740s" target="_blank" rel="noopener">12:20</a>)</li></ul><div class="sh">The demand factory</div><ul><li><strong>Too much working software:</strong> Customers didn&#39;t ask for more windows and buttons; they want gross margin, customers and brand differentiation. Engineers fluent with models should build the demand side and not wait for sales and marketing (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=740s" target="_blank" rel="noopener">12:20</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=830s" target="_blank" rel="noopener">13:50</a>)</li><li><strong>What it does:</strong> Agents decide which market questions to ask next, combine and re-rank the answers overnight, and plan experiments with limited capacity (for example, measuring price elasticity), so you can say yes to customers faster (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=830s" target="_blank" rel="noopener">13:50</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=940s" target="_blank" rel="noopener">15:40</a>)</li><li><strong>Fill your brand envelope:</strong> Spindrift adding caffeine is a reasonable stretch, but motor oil isn&#39;t, and an energy drink is. Find your &quot;energy drink&quot;: more customers, more SKUs, coherent product lines, then acquire your competitor, and start before they do (<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=940s" target="_blank" rel="noopener">15:40</a>–<a href="https://www.youtube.com/watch?v=1S4hx3wgvBE&amp;t=1083s" target="_blank" rel="noopener">18:03</a>)</li></ul></div></article><article class="it full" id="v-nRlqH4izAU8" data-title="They Rebuilt Prettier in Rust. It&#39;s 19× Faster... Sort Of." data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=nRlqH4izAU8" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+v+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=nRlqH4izAU8" target="_blank" rel="noopener">They Rebuilt Prettier in Rust. It&#39;s 19× Faster... Sort Of.</a></h3><div class="meta">Better Stack · Josh, Better Stack (on the open-source rust-anything tool) · uploaded 26 Nov, 7:15 PM IST · 7:45</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short (7:45), concrete, and honest about where the 19× claim falls apart.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 47 times before. New here: a concrete tool that records the original code&#39;s behavior on generated edge cases and won&#39;t approve the Rust port until every output matches.</div><div class="repeat">🔁 Repeat: &#39;Rust for AI tooling&#39; — seen 4 times before. New here: agent-driven ports of existing JS/TS/Python apps to Rust, with measured speedups and their caveats.</div><div class="repeat">🔁 Repeat: &#39;benchmark reliability&#39; — seen 5 times before. New here: the headline 19× drops to 4.2× once Node&#39;s startup time is removed, and nobody has reproduced the numbers yet.</div><div class="sh">What rust-anything does</div><ul><li><strong>Proves the rewrite, doesn&#39;t write it:</strong> Someone ported Prettier to Rust and claims it&#39;s 19× faster with byte-for-byte identical output. The tool behind it wrote no Rust. You or your agent write the port, and rust-anything checks it behaves exactly like the original before signing off (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=83s" target="_blank" rel="noopener">1:23</a>)</li><li><strong>Demo:</strong> cargo install rust-anything, then setup registers an MCP server and a Claude Code skill. bridge generates a Rust crate plus a wrapper so callers keep the same API. record runs the original TypeScript fuzzy-search function on generated edge cases (emoji, negative zero, overflow, sort order), and diff catches a planted bug: the emoji string scores differently because JavaScript&#39;s indexOf counts UTF-16 code units (an emoji is 2) and the Rust port counted 1 (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=83s" target="_blank" rel="noopener">1:23</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=178s" target="_blank" rel="noopener">2:58</a>)</li><li><strong>Full pipeline:</strong> profile finds hot functions, analyze lists what to port in what order with risks by file and line, and bridge supports Node, PyO3 and JNI. diff and bench check correctness and speed, shadow runs both in production but returns the original&#39;s answer, and gate requires rustfmt, clippy with warnings as errors, no unwrap/panic, an unsafe audit and code no bigger than 3× the original. It works with TS/JS, Python, C, Go and Ruby, and plugs into Claude Code, Codex and others via MCP (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=178s" target="_blank" rel="noopener">2:58</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=237s" target="_blank" rel="noopener">3:57</a>)</li><li><strong>Whole-app migration:</strong> Rust owns the entry point and anything not yet ported falls back to the original. It starts at 100% fallback and drops toward 0 with each unit, so a half-done port can ship (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=237s" target="_blank" rel="noopener">3:57</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=260s" target="_blank" rel="noopener">4:20</a>)</li></ul><div class="sh">The numbers and the catch</div><ul><li><strong>Claimed results:</strong> On Prettier 3.6.2 on a 16GB M4, formatting 2,300 JS/TS files took 129s in Prettier vs 6.9s in Rust, and about 16,000 of 17,000+ runs went fully through Rust. json-server went from 74MB idle to 3.5MB as a 5.3MB binary, with first response about 80ms to about 10ms. Fuse.js search over 50,000 strings went from 91ms to 2.8ms (32×) (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=260s" target="_blank" rel="noopener">4:20</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li><li><strong>Real speedup is 4.2×:</strong> The 19× is mostly Node startup (about 55ms per file vs about 3ms). Warmed up in the same process it&#39;s 600ms vs 143ms. About 8% of runs fall back to real Prettier, which helps explain the identical output, and HTML/Vue/Angular aren&#39;t ported (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=345s" target="_blank" rel="noopener">5:45</a>)</li><li><strong>When Rust loses:</strong> Calling Prettier&#39;s doc printer from JS through the bridge runs at about half the speed of plain JS, and a port of Vercel&#39;s ms library came out at 0.56×. Crossing the bridge has a cost, so run bench before porting tiny, frequently called functions (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=345s" target="_blank" rel="noopener">5:45</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=370s" target="_blank" rel="noopener">6:10</a>, <a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=440s" target="_blank" rel="noopener">7:20</a>)</li><li><strong>Caveats:</strong> All benchmarks are the creator&#39;s own on an M4 and not reproduced. There&#39;s no figure for tokens or hours spent. About 12,000 lines of Rust nobody wrote by hand are pinned to one Prettier version and need maintaining. The repo is days old with nearly 10,000 stars. If you only want a fast formatter, Biome and oxfmt already exist (<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=370s" target="_blank" rel="noopener">6:10</a>–<a href="https://www.youtube.com/watch?v=nRlqH4izAU8&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul></div></article></div>',1))])}const T=u(b,[["render",_]]);export{I as __pageData,T as default};
